use std::cmp::Ordering;

pub fn compare_versions(a: &str, b: &str) -> Ordering {
    let parts_a: Vec<&str> = a.split('.').collect();
    let parts_b: Vec<&str> = b.split('.').collect();

    let max_len = parts_a.len().max(parts_b.len());

    for i in 0..max_len {
