        let val_a: u32 = parts_a.get(i).and_then(|s| s.parse().ok()).unwrap_or(0);
        let val_b: u32 = parts_b.get(i).and_then(|s| s.parse().ok()).unwrap_or(0);

        match val_a.cmp(&val_b) {
